// This file is initial project-owned business source. Domainry will never overwrite it.
package service

import (
	"context"
	capabilities "example.com/m2-fieldservice/generated/capabilities"
	"example.com/m2-fieldservice/generated/data"
	"example.com/m2-fieldservice/generated/schema"
)

// StartAssignedRepair implements the project-owned work_order.start_assigned_repair Handler.
func StartAssignedRepair(ctx context.Context, caps capabilities.StartAssignedRepairCapabilities, input capabilities.StartAssignedRepairInput) (capabilities.StartAssignedRepairOutput, error) {
	if err := requireRequestID(input.RequestID); err != nil {
		return capabilities.StartAssignedRepairOutput{}, err
	}
	targetID := caps.Execution.TargetID()
	current, err := caps.WorkOrder.GetForUpdate(ctx, targetID)
	if err != nil {
		return capabilities.StartAssignedRepairOutput{}, err
	}
	principal := caps.Execution.Principal()
	if err := requireAssignee(principal, current); err != nil {
		return capabilities.StartAssignedRepairOutput{}, err
	}
	principalReference := schema.NewWorkOrderAssignedTechnicianIDReference(schema.IdentityUserID(principal.UserID))
	mutation := data.NewWorkOrderUpdate(targetID).
		RequireStatusEqual(schema.WorkOrderStatus("dispatched"), "work_order.invalid_state").
		RequireAssignedTechnicianIDEqual(principalReference, "work_order.assignee_required").
		SetStatus(schema.WorkOrderStatus("in_repair")).SetStartedAt(nowUTC()).WithExpectedUpdatedAt(current.UpdatedAt)
	updated, err := caps.WorkOrder.ConditionalUpdate(ctx, mutation)
	if err != nil {
		return capabilities.StartAssignedRepairOutput{}, err
	}
	return capabilities.StartAssignedRepairOutput{Status: schema.WorkOrderStartAssignedRepairStatus("in_repair"), WorkOrderID: updated.ID}, nil
}
