// DispatchWorkOrder implements the project-owned work_order.dispatch_work_order Handler.
func DispatchWorkOrder(ctx context.Context, caps capabilities.DispatchWorkOrderCapabilities, input capabilities.DispatchWorkOrderInput) (capabilities.DispatchWorkOrderOutput, error) {
	if err := requireRequestID(input.RequestID); err != nil {
		return capabilities.DispatchWorkOrderOutput{}, err
	}
	if input.TechnicianUserID == "" || input.TechnicianName == "" || input.OrganizationUnitID == "" {
		return capabilities.DispatchWorkOrderOutput{}, reject("work_order.dispatch_fields_required")
	}
	targetID := caps.Execution.TargetID()
	current, err := caps.WorkOrder.GetForUpdate(ctx, targetID)
	if err != nil {
		return capabilities.DispatchWorkOrderOutput{}, err
	}
	now := nowUTC()
	technician := schema.NewWorkOrderAssignedTechnicianIDReference(schema.IdentityUserID(input.TechnicianUserID))
	mutation := data.NewWorkOrderUpdate(targetID).
		RequireStatusEqual(schema.WorkOrderStatus("submitted"), "work_order.invalid_state").
		RequireAssignedTechnicianIDNull("work_order.already_assigned").
		SetAssignedTechnicianID(technician).
		SetAssignedTechnicianName(input.TechnicianName).
		SetOrganizationUnitID(schema.NewWorkOrderOrganizationUnitIDReference(schema.IdentityOrganizationUnitID(input.OrganizationUnitID))).
		SetAssignedAt(now).
		SetStatus(schema.WorkOrderStatus("dispatched")).
		WithExpectedUpdatedAt(current.UpdatedAt)
	updated, err := caps.WorkOrder.ConditionalUpdate(ctx, mutation)
	if err != nil {
		return capabilities.DispatchWorkOrderOutput{}, err
	}
	_, err = caps.Notifications.Dispatch(ctx, capabilities.DispatchWorkOrderNotificationIntent{
		EventType: "work_order.assigned", SourceEventID: input.RequestID,
		RecipientUserIDs: []string{input.TechnicianUserID}, Surface: "business_workspace",
		SubjectObjectKey: "work_order", SubjectRecordID: string(updated.ID), SubjectVersion: input.RequestID,
		DedupeKey: "work-order-assigned:" + input.RequestID, GroupKey: "work-order:" + string(updated.ID), Alert: true, OccurredAt: now,
	})
	if err != nil {
		return capabilities.DispatchWorkOrderOutput{}, err
	}
	return capabilities.DispatchWorkOrderOutput{Status: schema.WorkOrderDispatchWorkOrderStatus("dispatched"), WorkOrderID: updated.ID}, nil
}
