// ApproveWarrantyWaiver implements the project-owned warranty_waiver.approve_warranty_waiver Handler.
func ApproveWarrantyWaiver(ctx context.Context, caps capabilities.ApproveWarrantyWaiverCapabilities, input capabilities.ApproveWarrantyWaiverInput) (capabilities.ApproveWarrantyWaiverOutput, error) {
	if err := requireRequestID(input.RequestID); err != nil {
		return capabilities.ApproveWarrantyWaiverOutput{}, err
	}
	waiverID := caps.Execution.TargetID()
	waiver, err := caps.WarrantyWaiver.GetForUpdate(ctx, waiverID)
	if err != nil {
		return capabilities.ApproveWarrantyWaiverOutput{}, err
	}
	orderID := waiver.WorkOrderID.ID()
	order, err := caps.WorkOrder.GetForUpdate(ctx, orderID)
	if err != nil {
		return capabilities.ApproveWarrantyWaiverOutput{}, err
	}
	if order.QuotedAmount == nil {
		return capabilities.ApproveWarrantyWaiverOutput{}, reject("work_order.quoted_amount_required")
	}
	finalAmount, err := domain.Subtract(string(*order.QuotedAmount), string(waiver.RequestedAmount))
	if err != nil {
		return capabilities.ApproveWarrantyWaiverOutput{}, reject("warranty_waiver.invalid_amount")
	}
	principal := caps.Execution.Principal()
	if !principal.Known || principal.UserID == "" {
		return capabilities.ApproveWarrantyWaiverOutput{}, reject("identity.principal_required")
	}
	now := nowUTC()
	waiverMutation := data.NewWarrantyWaiverUpdate(waiver.ID).
		RequireResultEqual(schema.WarrantyWaiverResult("pending"), "warranty_waiver.not_pending").
		SetResult(schema.WarrantyWaiverResult("approved")).SetDecidedAt(now).SetDecidedByUserID(principal.UserID).
		WithExpectedUpdatedAt(waiver.UpdatedAt)
	updatedWaiver, err := caps.WarrantyWaiver.ConditionalUpdate(ctx, waiverMutation)
	if err != nil {
		return capabilities.ApproveWarrantyWaiverOutput{}, err
	}
	orderMutation := data.NewWorkOrderUpdate(order.ID).
		RequireStatusEqual(schema.WorkOrderStatus("completed"), "work_order.invalid_state").
		RequireWaiverResultEqual(schema.WorkOrderWaiverResult("pending"), "warranty_waiver.not_pending").
		SetWaiverResult(schema.WorkOrderWaiverResult("approved")).SetFinalAmount(schema.WorkOrderFinalAmount(finalAmount)).
		WithExpectedUpdatedAt(order.UpdatedAt)
	updatedOrder, err := caps.WorkOrder.ConditionalUpdate(ctx, orderMutation)
	if err != nil {
		return capabilities.ApproveWarrantyWaiverOutput{}, err
	}
	ledger := schema.CreateServiceChargeLedger{
		CalculationTrace:  fmt.Sprintf("rule=%s;decision=approved;final=%s", ruleVersion, finalAmount),
		EventKey:          "waiver-approved:" + input.RequestID,
		EventKind:         schema.ServiceChargeLedgerEventKind("waiver_approved"),
		FinalAmount:       schema.ServiceChargeLedgerFinalAmount(finalAmount),
		InputSnapshot:     fmt.Sprintf("quoted=%s;waiver=%s", *order.QuotedAmount, waiver.RequestedAmount),
		OccurredAt:        now,
		QuotedAmount:      schema.ServiceChargeLedgerQuotedAmount(*order.QuotedAmount),
		RuleVersion:       ruleVersion,
		ThresholdSnapshot: schema.ServiceChargeLedgerThresholdSnapshot(waiver.ThresholdSnapshot),
		WaiverAmount:      schema.ServiceChargeLedgerWaiverAmount(waiver.RequestedAmount),
		WarrantyWaiverID: func() *schema.ServiceChargeLedgerWarrantyWaiverIDReference {
			value := schema.NewServiceChargeLedgerWarrantyWaiverIDReference(waiver.ID)
			return &value
		}(),
		WorkOrderID: schema.NewServiceChargeLedgerWorkOrderIDReference(order.ID),
	}
	if waiver.RequestedByUserID != nil {
		technicianReference := schema.NewServiceChargeLedgerTechnicianUserIDReference(waiver.RequestedByUserID.ID())
		ledger.TechnicianUserID = &technicianReference
	}
	_, err = caps.ServiceChargeLedger.Create(ctx, ledger)
	if err != nil {
		return capabilities.ApproveWarrantyWaiverOutput{}, err
	}
	if waiver.RequestedByUserID != nil {
		_, err = caps.Notifications.Dispatch(ctx, capabilities.ApproveWarrantyWaiverNotificationIntent{
			EventType: "warranty_waiver.decided", SourceEventID: input.RequestID,
			RecipientUserIDs: []string{string(waiver.RequestedByUserID.ID())}, Surface: "business_workspace",
			SubjectObjectKey: "warranty_waiver", SubjectRecordID: string(updatedWaiver.ID), SubjectVersion: input.RequestID,
			DedupeKey: "waiver-approved:" + input.RequestID, GroupKey: "work-order:" + string(updatedOrder.ID), Alert: true, OccurredAt: now,
		})
		if err != nil {
			return capabilities.ApproveWarrantyWaiverOutput{}, err
		}
	}
	return capabilities.ApproveWarrantyWaiverOutput{Result: schema.WarrantyWaiverApproveWarrantyWaiverResult("approved"), WarrantyWaiverID: updatedWaiver.ID}, nil
}
