		requesterReference := schema.NewWarrantyWaiverRequestedByUserIDReference(schema.IdentityUserID(principal.UserID))
		createdWaiver, createErr := caps.WarrantyWaiver.Create(ctx, schema.CreateWarrantyWaiver{
			EligibilityAttested: true,
			RequestedAmount:     schema.WarrantyWaiverRequestedAmount(waiverAmount),
			RequestedAt:         now,
			RequestedByUserID:   &requesterReference,
			Result:              schema.WarrantyWaiverResult(waiverResult),
			ThresholdSnapshot:   schema.WarrantyWaiverThresholdSnapshot(waiverThreshold),
			WorkOrderID:         schema.NewWarrantyWaiverWorkOrderIDReference(order.ID),
		})
		if createErr != nil {
			return capabilities.CompleteRepairOutput{}, createErr
		}
		waiverRecord = &createdWaiver
	}

	ledgerInput := fmt.Sprintf("quoted=%s;waiver=%s;eligible=%t", quoted, waiverAmount, input.WarrantyEligible)
	ledgerTrace := fmt.Sprintf("rule=%s;threshold=%s;result=%s;final=%s", ruleVersion, waiverThreshold, waiverResult, finalAmount)
	ledgerTechnicianReference := schema.NewServiceChargeLedgerTechnicianUserIDReference(schema.IdentityUserID(principal.UserID))
	ledger := schema.CreateServiceChargeLedger{
		CalculationTrace:  ledgerTrace,
		EventKey:          "repair-completed:" + input.RequestID,
		EventKind:         schema.ServiceChargeLedgerEventKind("repair_completed"),
		FinalAmount:       schema.ServiceChargeLedgerFinalAmount(finalAmount),
		InputSnapshot:     ledgerInput,
		OccurredAt:        now,
		QuotedAmount:      schema.ServiceChargeLedgerQuotedAmount(quoted),
		RuleVersion:       ruleVersion,
		TechnicianUserID:  &ledgerTechnicianReference,
		ThresholdSnapshot: schema.ServiceChargeLedgerThresholdSnapshot(waiverThreshold),
		WaiverAmount:      schema.ServiceChargeLedgerWaiverAmount(waiverAmount),
		WorkOrderID:       schema.NewServiceChargeLedgerWorkOrderIDReference(order.ID),
	}
	if waiverRecord != nil {
		waiverReference := schema.NewServiceChargeLedgerWarrantyWaiverIDReference(waiverRecord.ID)
		ledger.WarrantyWaiverID = &waiverReference
	}
	if _, err = caps.ServiceChargeLedger.Create(ctx, ledger); err != nil {
		return capabilities.CompleteRepairOutput{}, err
	}
	principalReference := schema.NewWorkOrderAssignedTechnicianIDReference(schema.IdentityUserID(principal.UserID))
	workOrderMutation := data.NewWorkOrderUpdate(order.ID).
		RequireStatusEqual(schema.WorkOrderStatus("in_repair"), "work_order.invalid_state").
		RequireAssignedTechnicianIDEqual(principalReference, "work_order.assignee_required").
		RequireCompletedAtNull("work_order.already_completed").
		SetQuotedAmount(schema.WorkOrderQuotedAmount(quoted)).
		SetWaiverAmount(schema.WorkOrderWaiverAmount(waiverAmount)).
		SetWaiverResult(schema.WorkOrderWaiverResult(waiverResult)).
		SetFinalAmount(schema.WorkOrderFinalAmount(finalAmount)).
		SetCompletedAt(now).
		SetStatus(schema.WorkOrderStatus("completed")).
		WithExpectedUpdatedAt(order.UpdatedAt)
	if waiverRecord != nil {
		workOrderMutation = workOrderMutation.SetWarrantyWaiverRecordID(string(waiverRecord.ID))
	}
	updated, err := caps.WorkOrder.ConditionalUpdate(ctx, workOrderMutation)
	if err != nil {
		return capabilities.CompleteRepairOutput{}, err
	}
	return capabilities.CompleteRepairOutput{
		FinalAmount:  schema.WorkOrderFinalAmount(finalAmount),
		Status:       schema.WorkOrderCompleteRepairStatus("completed"),
		WaiverResult: schema.WorkOrderCompleteRepairWaiverResult(waiverResult),
		WorkOrderID:  updated.ID,
	}, nil
}

type completionLine struct {
	partID   schema.SparePartID
	quantity int64
}

func completionLines(input capabilities.CompleteRepairInput) ([]completionLine, error) {
	lines := []completionLine{{partID: input.SparePart1ID, quantity: input.SparePart1Quantity}}
	optional := []struct {
		id       *schema.SparePartID
		quantity *int64
	}{{input.SparePart2ID, input.SparePart2Quantity}, {input.SparePart3ID, input.SparePart3Quantity}}
	for _, candidate := range optional {
		if (candidate.id == nil) != (candidate.quantity == nil) {
			return nil, reject("part_usage.incomplete_line")
		}
		if candidate.id != nil {
			lines = append(lines, completionLine{partID: *candidate.id, quantity: *candidate.quantity})
		}
	}
	seen := make(map[schema.SparePartID]struct{}, len(lines))
	for _, line := range lines {
		if line.partID == "" || line.quantity <= 0 {
			return nil, reject("part_usage.invalid_line")
		}
		if _, exists := seen[line.partID]; exists {
			return nil, reject("part_usage.duplicate_spare_part")
		}
		seen[line.partID] = struct{}{}
	}
	return lines, nil
}
