package service

import (
	"context"
	capabilities "example.com/m2-fieldservice/generated/capabilities"
	"example.com/m2-fieldservice/generated/schema"
	"time"
)

// SendOverdueReminder implements the project-owned work_order.send_overdue_reminder Handler.
func SendOverdueReminder(ctx context.Context, caps capabilities.SendOverdueReminderCapabilities, input capabilities.SendOverdueReminderInput) (capabilities.SendOverdueReminderOutput, error) {
	if err := requireRequestID(input.RequestID); err != nil {
		return capabilities.SendOverdueReminderOutput{}, err
	}
	if input.ScheduledAt.IsZero() {
		return capabilities.SendOverdueReminderOutput{}, reject("scheduler.scheduled_at_required")
	}
	order, err := caps.WorkOrder.Get(ctx, caps.Execution.TargetID())
	if err != nil {
		return capabilities.SendOverdueReminderOutput{}, err
	}
	if string(order.Status) != "dispatched" || order.AssignedAt == nil || order.AssignedTechnicianID == nil {
		return capabilities.SendOverdueReminderOutput{}, reject("work_order.not_overdue_candidate")
	}
	if input.ScheduledAt.Sub(*order.AssignedAt) <= 48*time.Hour {
		return capabilities.SendOverdueReminderOutput{}, reject("work_order.not_overdue")
	}
	shanghai := time.FixedZone("Asia/Shanghai", 8*60*60)
	businessDate := input.ScheduledAt.In(shanghai)
	if businessDate.Weekday() == time.Saturday || businessDate.Weekday() == time.Sunday {
		return capabilities.SendOverdueReminderOutput{}, reject("scheduler.business_day_required")
	}
	recipientID := string(order.AssignedTechnicianID.ID())
	recipientReference := schema.NewOverdueReminderRecipientUserIDReference(order.AssignedTechnicianID.ID())
	dateKey := businessDate.Format("2006-01-02")
	reminder, err := caps.OverdueReminder.Create(ctx, schema.CreateOverdueReminder{
		BusinessDate:    businessDate,
		RecipientUserID: &recipientReference,
		ReminderKey:     string(order.ID) + ":" + dateKey,
		SentAt:          input.ScheduledAt.UTC(),
		Status:          schema.OverdueReminderStatus("delivered"),
		WorkOrderID:     schema.NewOverdueReminderWorkOrderIDReference(order.ID),
	})
	if err != nil {
		return capabilities.SendOverdueReminderOutput{}, err
	}
	requestNo := string(order.RequestNo)
	_, err = caps.Notifications.Dispatch(ctx, capabilities.SendOverdueReminderNotificationIntent{
		EventType: "work_order.overdue", SourceEventID: input.RequestID,
		RecipientUserIDs: []string{recipientID}, Surface: "business_workspace",
		SubjectObjectKey: "work_order", SubjectRecordID: string(order.ID), SubjectVersion: input.RequestID,
		DedupeKey: "work-order-overdue:" + string(order.ID) + ":" + dateKey,
		GroupKey:  "work-order:" + string(order.ID), Alert: true, OccurredAt: input.ScheduledAt.UTC(),
		Variables: []capabilities.SendOverdueReminderNotificationVariable{{Key: "request_no", StringValue: &requestNo}},
	})
	if err != nil {
		return capabilities.SendOverdueReminderOutput{}, err
	}
	return capabilities.SendOverdueReminderOutput{ReminderID: reminder.ID, Status: schema.WorkOrderSendOverdueReminderStatus("delivered")}, nil
}

